-- Wissensseite Praxis-Examen (21.10.2026), aktiv=false bis zur Freigabe. In 6 kurzen Schritten nacheinander ausführen (Mobil-Editor kürzt lange Zeilen).
-- Freigabe danach: update lerninhalte set aktiv=true, geprueft_von='Patrick Schenkelberger, Fachpfleger Anästhesie und Intensivmedizin', geprueft_am=current_date where slug='praktische-pruefung-ablauf';
insert into lerninhalte (typ, kategorie, slug, titel, daten, aktiv, quelle, stand) select 'grundlagen', 'Pflegefachwissen', 'praktische-pruefung-ablauf', 'Praktische Prüfung im Pflegeexamen: Ablauf Schritt für Schritt', '{"definition": "Die praktische Prüfung im Pflegeexamen findet in einer echten, komplexen Pflegesituation statt. Du versorgst mindestens zwei Menschen, einen davon mit erhöhtem Pflegebedarf, und zeigst den ganzen Pflegeprozess: Pflegebedarf erheben, planen, durchführen, steuern und evaluieren (PflAPrV § 16).", "einteilung": "Vier Bausteine: Vorbereitungsteil (Pflegeplanung unter Aufsicht) · Fallvorstellung (höchstens 20 Minuten) · Durchführung der geplanten und situativ nötigen Pflege · Reflexionsgespräch (höchstens 20 Minuten). Ohne Vorbereitungsteil dauert die Prüfung höchstens 240 Minuten.", "merksatz": "Erst die Person, dann der Plan: Wer begründet abweicht, punktet.", "haeufige_pruefungsfrage": "Wie lange dauern Fallvorstellung und Reflexionsgespräch in der praktischen Prüfung?"}'::jsonb, false, 'PflAPrV § 16; Erfahrungswerte aus der Praxisanleitung', current_date where not exists (select 1 from lerninhalte where slug='praktische-pruefung-ablauf');
update lerninhalte set daten = daten || '{"tabelle": {"kopf": ["Schritt", "Was du tust", "Worauf es ankommt"], "zeilen": [["Vortag", "Zwei Menschen mit der Praxisanleitung auswählen, kennenlernen, Einverständnis einholen, Pflegebedarf und Ressourcen erheben", "Einer mit erhöhtem Pflegebedarf; Einverständnis ist Pflicht"], ["Vortag", "Informationssammlung, Pflegeplanung und Zeitplan schreiben, Pflegewagen, Medikamente und Infusionen vorbereiten", "Realistischer Zeitplan mit Puffer; Verfallsdatum und Charge prüfen"], ["Vor dem Start", "Übergabe vom Nachtdienst anhören, Veränderungen erfragen, ruhigen Raum organisieren", "Planung bei Veränderungen anpassen"], ["1. Fallvorstellung", "Beide Menschen strukturiert vorstellen, geplanten Ablauf erklären", "Höchstens 20 Minuten, Prioritäten statt Vollständigkeit"]]}}'::jsonb where slug='praktische-pruefung-ablauf';
update lerninhalte set daten = jsonb_set(daten, '{tabelle,zeilen}', (daten->'tabelle'->'zeilen') || '[["2. Richten", "Medikamente richten, Infusionen vorbereiten", "Infusionen erst kurz vor der Gabe vorbereiten"], ["3. Versorgung", "Begrüßen, Vitalzeichen, Schmerz und Ausscheidung erfragen, geplante Pflege, Prophylaxen, Medikamente, Verbände und Zugänge, Umgebung aufräumen", "Immer an der Person orientiert; Abweichungen begründen"], ["4. Dokumentation", "Durchführungsnachweis, Verlaufsbericht, ggf. Wund-, Bilanz-, Blutzuckerbogen", "Nur wirklich Erledigtes abzeichnen; Vitalzeichen zeitnah"]]'::jsonb) where slug='praktische-pruefung-ablauf';
update lerninhalte set daten = jsonb_set(daten, '{tabelle,zeilen}', (daten->'tabelle'->'zeilen') || '[["5. Aufräumen", "Material, Pflegewagen und Flächen desinfizieren", "Hygiene bis zum Schluss"], ["6. Übergabe", "An Praxisanleitung bzw. zuständige Pflegefachperson übergeben", "Vitalzeichen, Befinden, Besonderheiten, tatsächlich durchgeführte Pflege"], ["7. Reflexion", "Was lief gut, wo bist du abgewichen und warum, was machst du nächstes Mal anders", "Höchstens 20 Minuten; ehrlich und konkret"]]'::jsonb) where slug='praktische-pruefung-ablauf';
update lerninhalte set daten = daten || '{"pruefungswissen": "Die Fallvorstellung und das Reflexionsgespräch dauern jeweils höchstens 20 Minuten. In der Psychiatrie steht statt der körperlichen Versorgung die geplante Pflege mit beiden Menschen im Mittelpunkt: Gespräche, Aktivitäten, Beratung und Begleitung im Alltag oder in Gruppen. Raum, Zeiten und Material regelt jede Einrichtung selbst – den Hausablauf mit der Praxisanleitung klären.", "pflegeschwerpunkt": "Plane nach den Gewohnheiten der zu pflegenden Menschen, nicht nach deinem Zeitplan. Abweichen vom Plan ist erlaubt und zeigt Kompetenz, wenn du es fachlich begründest."}'::jsonb where slug='praktische-pruefung-ablauf';
update lerninhalte set daten = daten || '{"mcq": [{"frage": "Wie viele Menschen versorgst du in der praktischen Prüfung mindestens?", "richtig": 2, "optionen": ["Einen", "Drei", "Zwei, einen davon mit erhöhtem Pflegebedarf", "So viele wie auf der Station liegen"]}, {"frage": "Wie lange darf die Fallvorstellung höchstens dauern?", "richtig": 1, "optionen": ["10 Minuten", "20 Minuten", "45 Minuten", "60 Minuten"]}]}'::jsonb where slug='praktische-pruefung-ablauf';
